"""Reproducible editorial data builder for GY1986 records 698--712.

All authored text is confined to parts/C. Run after editing to checkpoint JSON,
CSV, and bibliographic data. Sources and search results are in ../evidence.
"""
from pathlib import Path
import json, csv, re

ROOT = Path(__file__).resolve().parents[1]
talks, items, problems, corrections = [], [], [], []

def talk(record, date, speaker, pages, title, summary, kind='talk'):
    talks.append(dict(record=record,date=date,speaker=speaker,pages=pages,title=title,kind=kind,summary=summary))

def item(record, pages, kind, title, notes, statement, fate, refs=(), cls='E',
         reconstruction='', correctness='correct with missing hypotheses', match='exact',
         verification='read the result', development='annotated', problem='', worth='',
         confidence='high', speaker=None, status=None):
    n=1+sum(x['record']==record for x in items)
    x=dict(id=f'1986-{record}.{n}',record=record,pages=pages,kind=kind,title=title,
           notes=notes,statement=statement,reconstruction=reconstruction,**{'class':cls},fate=fate,
           present_status=status or r'As of 12 November 2026, the precise statement above is established; the qualifications distinguish it from the abbreviated notebook formulation.',
           literal_correctness=correctness,publication_match=match,verification=verification,
           development=development,problem=problem,worth=worth,refs=list(refs),confidence=confidence)
    if speaker: x['speaker']=speaker
    items.append(x)
    return x['id']

def problem(pid,title,statement,occurrences,status,refs):
    problems.append(dict(id=pid,title=title,statement=statement,occurrences=occurrences,
                         status=status,status_date='2026-11',refs=refs))

def correction(page,place,reads,should,evidence,applies='both',kind='faithful_error'):
    corrections.append(dict(page=page,place=place,transcription_reads=reads,should_read=should,
                            evidence=evidence,applies_to=applies,type=kind))

def save():
    for name, data in [('talks',talks),('items',items),('problems',problems)]:
        (ROOT/f'{name}.json').write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n')
    with (ROOT/'corrections.csv').open('w',newline='') as f:
        w=csv.DictWriter(f,fieldnames=['page','place','transcription_reads','should_read','evidence','applies_to','type'])
        w.writeheader();w.writerows(corrections)

talk(698,'1986-11-24','V. A. Kazakov','P001329-P001334','Unitary integrals and the Ising model on random planar maps',r'The identifiable talk begins on P001330. It moves from a unitary integral with several diagonal sources and reduced gauge models to the two-matrix representation of an Ising model on fluctuating planar maps. The ordinary Harish-Chandra--Itzykson--Zuber integral and biorthogonal-polynomial reduction are the calculational bridge. P001329 belongs to the preceding discussion; the February lecture starts on P001333.')
talk(699,'','-','P001332-P001334','YEAR 1987',r'This is a catalogue heading marking the calendar-year transition, not a second mathematical lecture. The last Kazakov formulas occupy P001332; the next explicit manuscript date is 9 February 1987 on P001333. No independent mathematical occurrence is assigned to this structural record.','heading')
talk(700,'1987-02-09','Don Zagier','P001332-P001344','Hecke traces, Eisenstein series, and the Riemann hypothesis',r'After a question about polygon gluings, Zagier develops level-one modular forms, Hecke operators and a kernel proof of the Eichler--Selberg trace formula. The second half concerns Eisenstein series, horocycle averages and toroidal automorphic forms. Several normalizing constants in the notebook require correction. The talk ends at the dated heading on P001343; the wide catalogue interval overlaps both neighbours.')
talk(701,'1987-02-16','Don Zagier','P001342-P001350','Critical values and rational periods of modular forms',r'The lecture connects even zeta-values, Eisenstein series and Mellin transforms of cusp forms, then explains the two rational period structures of Hecke eigenforms using Rankin unfolding. It explicitly points to Kohnen and Zagier\textquoteright s already published work on rational periods. The manuscript heading is on P001343 and the next lecture begins on P001349.')
talk(702,'1987-03-02','V. A. Kazakov','P001348-P001356','Gaussian matrix integrals and polygon gluings',r'The talk gives the matrix-integral derivation of the Harer--Zagier enumeration of orientable polygon gluings, including Wick pairings, Hermitian eigenvalues, Hermite polynomials and generating functions. It closes with variants having triangular faces and colours. The identifiable text occupies P001349--P001354.')
talk(703,'1987-03-09','A. A. Beilinson','P001354-P001356','Zeta functions, regulators, and Artin L-functions',r'Beilinson\textquoteright s explicit heading is on P001355 after Gelfand\textquoteright s factor discussion. His exposition continues through P001358, beyond the catalogue endpoint: archimedean and nonarchimedean local factors, special values, regulators, p-adic interpolation and Artin L-functions. The attribution follows the manuscript headings rather than the overlapping catalogue spans.')
talk(704,'1987-03-09','I. M. Gelfand','P001354-P001358','Fractal measures, factors, and proposed connections',r'The short Gelfand preamble on P001355 proposes connections among fractional-dimensional measures, representations, factors and chaotic dynamics. It includes a recognizable reference to the uniqueness of the hyperfinite type III\(_1\) factor, recorded with a problematic type label. The following explicit Beilinson heading controls attribution of the zeta-function material.')
talk(705,'1987-03-23','V. E. Zakharov','P001359-P001364','Dressing methods and spectral differential operators',r'Zakharov reviews the Marchenko and nonlocal d-bar dressing constructions and then considers commuting operators that differentiate in the spectral parameter. The novelty claim concerns this last extension, not inverse scattering itself. Several displayed Lax and matrix identities have sign or hypothesis problems. The Migdal heading appears partway down P001363.')
talk(706,'1987-03-23','A. A. Migdal','P001362-P001369','Matrix loop equations and Wilson loops',r'Migdal derives Schwinger--Dyson identities for matrix traces, planar factorization and the resolvent equation, before connecting them with gauge-theory loop equations. Gelfand interrupts with the cube-plane problem and its answer 96. The next dated meeting begins on P001368; P001362 and the beginning of P001363 remain Zakharov\textquoteright s.')
talk(707,'1987-04-13','A. S. Schwarz','P001367-P001369','Super Riemann surfaces and string measures',r'The Schwarz heading occurs on P001369 after Sinai\textquoteright s discussion and continues into P001371. The talk treats superconformal distributions, moduli, periods, super Selberg formulas and determinants in string theory. Statements about uniformization, free modules and determinant powers need qualifications; the catalogue record number, date and interval are retained, with the manuscript order identified explicitly.')
talk(708,'1987-04-13','Ya. G. Sinai','P001367-P001372','Spin glasses and ultrametricity',r'Sinai\textquoteright s discussion on P001368--P001369 distinguishes finite-range spin glasses from the mean-field model, raises the thermodynamic ground-state problem, and describes the Parisi picture of hierarchical overlaps. Later theorems settle carefully specified mean-field assertions, but do not justify the literal finite-size statement of many exactly degenerate ground states.')
talk(709,'1987-04-13','D. V. Alekseevskii','P001370-P001375','Quaternionic structures and integrability',r'The Alekseevskii heading on P001371 introduces the failure of a naive quaternionic differentiability condition, quaternionic projective changes of coordinates, and the invariant rank-three bundle of almost complex structures. The discussion distinguishes torsion-free quaternionic geometry from a chosen hypercomplex triple and includes a twistor-style integrability proposal.')
talk(710,'1987-04-20','A. A. Kirillov','P001373-P001377','Hecke algebras, braids, and link invariants',r'After Gelfand\textquoteright s incompletely specified question about commuting partially defined isometries, Kirillov explains Hecke algebras, braid groups and Markov traces. The notes conflate algebraic traces, positive traces and factor representations, and the observation about roots of unity should be read against Jones\textquoteright s pre-existing index theorem.')
talk(711,'1987-04-20','A. A. Beilinson','P001375-P001379','Holomorphic Chern classes and their integral comparison',r'The explicit Beilinson heading on P001376 starts with Chern classes and their Hodge and integral structures, then formulates the comparison problem using transition functions and logarithms. This is the introduction to the following week\textquoteright s Deligne-cohomology lecture, not a second copy of that lecture.')
talk(712,'1987-04-27','A. A. Beilinson','P001377-P001384','Deligne cohomology, motivic complexes, and the dilogarithm',r'The lecture defines the Deligne complex, its products and characteristic classes, explains the intermediate-Jacobian exact sequence, and sketches motivic refinements and the weight-two dilogarithmic complex. It cites the MPI 87-2 preprint explicitly. The last cross-ratio construction is best matched to the low-weight motivic characteristic-class program; its abbreviation is not a proof of the general motivic conjectures.')

item(698,'P001330','question','The unitary integral with two independent diagonal sources',r'Kazakov asks to calculate \(\int d\Omega\,\exp\sum_{\mu=1}^{2}\operatorname{Tr}(\Omega^\dagger p_\mu\Omega q_\mu)\), with diagonal \(p_\mu,q_\mu\), and says that the two-dimensional case has not been calculated.',r'For prescribed diagonal complex \(N\times N\) matrices \(P_1,P_2,Q_1,Q_2\), determine \(Z_N=\int_{U(N)}\exp\{\sum_{\mu=1}^{2}\operatorname{Tr}(U^*P_\mu UQ_\mu)\}\,dU\), where Haar measure has mass one. Distinguish an exact convergent series, an efficient finite formula, and a useful large-\(N\) analysis.',r'\citet[Eq.~(3), Sections~2.2--2.3 and Appendix]{holguin2024multimatrix} study this same integral, obtaining an explicit \(U(2)\) expression and a \(U(3)\) expansion; their preprint appeared on 6 July 2023 and the article on 4 April 2024. They also identify the obstruction to a naive extension of the one-source localization formula. The chapter supplies an explicitly labelled rederivation and general convergent Haar expansion, not a claim of a new closed solution.',('holguin2024multimatrix',),cls='C',reconstruction=r'Haar normalization, complex parameters and the distinction among meanings of ``calculate'' are editorial specifications. The notebook states no particular target form of answer.',problem='GP-1986-60',worth=r'Worth developing in a bounded form: a checked finite-rank formula and a convergent expansion with an error bound make the original computational question concrete without claiming a general closed-form solution.',development='developed in this chapter',status=r'As of 12 November 2026, exact series evaluation is available and the two-dimensional unitary rank is explicit. A compact formula comparable to the one-source determinant, together with the desired general large-\(N\) control, is not supplied by the cited work; these stronger targets must not be conflated with the existence of an exact evaluation series.')
item(698,'P001330','method','Expansion near the identity and planar perturbation theory',r'The notes put \(\Omega=e^{iA}\), isolate a Gaussian part, expand the rest of the exponential and the Haar measure, and retain planar diagrams.',r'An expansion about a specified nondegenerate saddle of a unitary matrix integral produces Gaussian Wick contractions and interaction vertices, including the Jacobian of exponential coordinates. At fixed formal order, double-line contractions are sorted by the Euler characteristic of their ribbon graph; planar terms are the leading powers of \(N\) under the usual matrix scaling.',r'This is the established matrix-model diagrammatic method of \citet[Sections~2--3]{bessisitzyksonzuber1980graphical}. It does not itself establish convergence or select the dominant saddle of the multi-source integral.',('bessisitzyksonzuber1980graphical',),reconstruction=r'The saddle and normalization conditions are necessary additions. The notebook does not justify a globally valid identity-centred expansion.',match='partial')
item(698,'P001331','claim','One-site reduction of lattice gauge theory',r'A product of \(d\) unitary integrals with plaquette traces is asserted to be equivalent to the ordinary gauge theory as \(N\to\infty\).',r'The Eguchi--Kawai loop-equation reduction requires, in addition to large-\(N\) factorization, the unbroken centre symmetry that annihilates open reduced loops. The unrestricted equivalence of the original one-site model at every coupling is false; in the relevant weak-coupling regime the centre symmetry can break.',r'\citet{eguchikawai1982reduction} proposed the reduction in 1982. \citet[abstract and model construction]{bhanothellerneuberger1982quenched} identified the symmetry-breaking obstruction and proposed quenching in the same year. This also connects with occurrences 1982-565.3--1982-565.6, but is not identical to the earlier specific free-energy problem.',('eguchikawai1982reduction','bhanothellerneuberger1982quenched'),correctness='false as written',match='partial',verification='publisher metadata checked')
item(698,'P001331','construction','Two-matrix Ising model on random quadrangulations',r'The integral has Gaussian coupling \(2cuv\) and separate quartic vertices \(u^4+v^4\); it is said to count two-coloured quadrangular decompositions with a weight for interfaces.',r'Treated as a formal expansion of a normalized two-Hermitian-matrix Gaussian integral with positive-definite quadratic covariance, the connected free energy sums connected orientable ribbon graphs. Quartic vertices are assigned one of two colours; dualization gives quadrangulations with an Ising spin on each dual face or original vertex, according to convention. Graphs carry automorphism factors, and the mixed propagator fixes the domain-wall weight.',r'\citet{kazakov1986ising} gives the exact planar Ising solution on a fluctuating lattice. The journal article appeared on 8 December 1986, shortly after the recorded 24 November talk; publication metadata verifies the identification, while the precise notebook parametrization needs the original conventions. The general graphical framework is already in \citet{bessisitzyksonzuber1980graphical}.',('kazakov1986ising','bessisitzyksonzuber1980graphical'),cls='A',reconstruction=r'Formal expansion, connectedness, automorphism weights and the distinction between the Gaussian parameter \(c\) and an exponential Ising coupling have been supplied. The displayed \(e^{2cm}\) cannot simply use the same \(c\) as the quadratic matrix coupling.',match='partial',verification='publisher metadata checked')
item(698,'P001331','theorem','Hermitian diagonalization and the Vandermonde square',r'Diagonalization of each matrix produces \(\Delta(x)^2\Delta(y)^2\) and one relative unitary integration.',r'For an integrable conjugation-invariant function on Hermitian \(N\times N\) matrices, Lebesgue measure disintegrates into a convention-dependent constant times \(\prod_i dx_i\,\Delta(x)^2\) and normalized orbit measure. For two matrices the relative eigenbasis is Haar distributed; stabilizers and eigenvalue permutations are included in the constant.',r'\citet[Hermitian eigenvalue reduction]{bessisitzyksonzuber1980graphical} use precisely this reduction in matrix enumeration. The square, rather than a single Vandermonde, is essential before the angular integral.',('bessisitzyksonzuber1980graphical',))
item(698,'P001331','theorem','The one-source unitary orbital integral',r'The angular integral is written as \(\det(e^{2cx_i y_j})/[\Delta(x)\Delta(y)]\), without a normalizing factor.',r'For normalized Haar measure and pairwise distinct eigenvalues, \[\int_{U(N)} e^{t\operatorname{Tr}(XUYU^*)}\,dU=\left(\prod_{j=1}^{N-1}j!\right)t^{-N(N-1)/2}\frac{\det(e^{tx_i y_j})}{\Delta(x)\Delta(y)}.\] Coincident eigenvalues and \(t=0\) are interpreted by analytic continuation of the removable singularities.',r'The matrix-integral form is the established formula in \citet{itzyksonzuber1980planar}. The omitted \(t\)-dependent factor matters if the notebook equality is literal; some eigenvalue-independent constants can instead be absorbed into a partition-function normalization.',('itzyksonzuber1980planar',),correctness='false as written')
item(698,'P001332','construction','Biorthogonal polynomials and the partition-function product',r'Polynomials are orthogonal for a two-variable weight. The notebook gives a moment determinant and a product of norms as the matrix integral.',r'For a bilinear moment functional \(\langle f,g\rangle=\iint f(x)g(y)w(x,y)\,dx\,dy\), assume all leading moment minors are nonzero. Unique monic families \(P_n,Q_n\) satisfy \(\langle P_n,Q_m\rangle=h_n\delta_{nm}\). A determinant formula for a monic polynomial must be divided by its leading moment minor. For symmetric weight one may take \(P_n=Q_n\). Andr\'eief expansion gives the labelled eigenvalue integral \(N!\prod_{n=0}^{N-1}h_n\), before any angular normalization.',r'The orthogonal and biorthogonal reduction belongs to the established matrix method; see \citet{bessisitzyksonzuber1980graphical} and the two-matrix application in \citet{kazakov1986ising}. The factorial and index shifts depend on whether the eigenvalues are ordered; the notebook does not state that convention.',('bessisitzyksonzuber1980graphical','kazakov1986ising'),correctness='false as written',match='partial')
item(698,'P001332','claim','Parametric planar free energy and its critical points',r'The notes give \(g(z)=z/(1-3z)^2-c^2z+3c^2z^3\), an integral expression for \(F\), and locate singularities by \(g^{\prime}(z)=0\).',r'On the branch of the stated parametric solution analytic at the Gaussian point, critical points of the inverse relation \(z=z(g)\) occur where \(g^{\prime}(z)=0\), unless a singularity or cancellation changes the local analysis. Extracting asymptotics of map coefficients additionally requires identifying the dominant singularity and the order of vanishing. The displayed free-energy integral depends on the partition-function normalization.',r'The explicit two-matrix Ising solution is identified by \citet{kazakov1986ising}. Its publication metadata is verified, but a line-by-line match of the notebook free-energy normalization is not asserted. The inverse-function criterion explains the stated mechanism; the notebook alone does not justify the claimed global asymptotics.',('kazakov1986ising',),cls='A',correctness='correct with missing hypotheses',match='partial',verification='publisher metadata checked',confidence='medium',status=r'As of 12 November 2026, the planar Ising matrix model is exactly solved. The present identification is of the model and critical-point mechanism; the precise additive and multiplicative normalization of the notebook expression remains an editorial qualification.')
problem('GP-1986-60','The two-source unitary orbital integral',r'Evaluate \(\int_{U(N)}\exp\sum_{\mu=1}^2\operatorname{Tr}(U^*P_\mu UQ_\mu)\,dU\) for diagonal source matrices, specifying whether the target is a convergent series, a compact finite formula or large-\(N\) information.',['1986-698.1'],r'As of 12 November 2026, the general integral has exact convergent Haar expansions; an explicit rank-two formula and rank-three expansions appear in \citet{holguin2024multimatrix}. The chapter develops a checked finite-rank formula and controlled series. No general compact HCIZ-type determinant or general large-\(N\) solution is claimed.',['holguin2024multimatrix'])
correction('P001331','ordinary angular integral','determinant divided by two Vandermondes','Multiply by the normalized-Haar factor product(j!,j=1,...,N-1)/(2c)^(N(N-1)/2).','The original scan contains no such factor; the missing normalization is a faithful mathematical abbreviation, not a translation error.')
correction('P001332','monic moment determinant','moment determinant without denominator','Divide by the leading moment minor to make the polynomial monic.','Russian and original scan agree; expansion in the leading power gives that minor, not 1.')
correction('P001332','product of biorthogonal norms','product h_i, i=1,...,N','For labelled eigenvalues use N! product h_i, i=0,...,N-1, together with the declared angular normalization.','The scan does not declare ordered eigenvalues; the necessary convention is absent.')
correction('P001329-P001334','catalogue boundary of record 698','whole range attributed to Kazakov','Kazakov heading on P001330; P001329 is the preceding discussion and 9 February 1987 starts on P001333.','Explicit speaker and date headings in the Russian manuscript.','both','provenance')
save()

# Record 700: modular forms and toroidal automorphic forms.
item(700,'P001333','remark','Faltings and p-adic string theory',r'Gelfand mentions Faltings in connection with p-adic strings, without a mathematical assertion or bibliographic identification.',r'The record preserves a thematic pointer to p-adic approaches to string theory. It specifies neither a p-adic curve, a moduli problem, nor an amplitude to calculate.',r'No exact theorem or problem can be recovered from this sentence. It is not legitimate to identify it with an arbitrary later paper on p-adic strings.',(),cls='F',correctness='not determinable',match='none found',verification='unresolved lead',development='none',confidence='low',speaker='I. M. Gelfand',status=r'As of 12 November 2026, the mathematical referent of this particular remark remains unidentified; this is a source limitation, not a claim that the subject was undeveloped.')
item(700,'P001333','question','Genus enumeration of oriented polygon gluings',r'Pair the sides of an oriented \(2n\)-gon with opposite orientation; cyclic rotations remain distinguishable. Count the resulting surfaces by genus.',r'Let \(\epsilon_g(n)\) count perfect matchings of the labelled sides of a fixed oriented \(2n\)-gon, glued orientation-reversingly, whose quotient is a connected closed oriented surface of genus \(g\). The number is zero for \(2g>n\). Labels fix a boundary root, so no quotient by rotation is taken.',r'\citet[Theorem~2 and its recurrence]{harerzagier1986euler} had already solved this enumeration in 1986. The later Kazakov lecture 1986-702 gives the matrix-integral derivation. The connection is to orbifold Euler characteristics of moduli spaces; Teichm\"uller space itself is contractible.',('harerzagier1986euler',),problem='GP-1986-62')
item(700,'P001333-P001334','definition','Level-one holomorphic modular and cusp forms',r'The notes impose the weight transformation law, Fourier expansion and vanishing at infinity, but write determinant \(\pm1\) and a negative Fourier exponent.',r'For even \(k\), a level-one modular form is holomorphic on \(\mathbb H\), satisfies \(f((az+b)/(cz+d))=(cz+d)^kf(z)\) for \(\left(\begin{smallmatrix}a&b\\c&d\end{smallmatrix}\right)\in SL_2(\mathbb Z)\), and is holomorphic at the cusp. Thus \(f(z)=\sum_{n\ge0}a_nq^n\), \(q=e^{2\pi iz}\); a cusp form has \(a_0=0\). Matrices of determinant \(-1\) do not act holomorphically on \(\mathbb H\) by this formula.',r'This is the classical setting fixed explicitly in \citet[Section~1]{zagier1977quadratic} and \citet[Section~1]{kohnenzagier1984periods}. The manuscript signs are faithfully transcribed but mathematically inconsistent with its later definition of \(q\).',('zagier1977quadratic','kohnenzagier1984periods'),correctness='false as written')
item(700,'P001334','theorem','Integral bases, small weights, and the discriminant form',r'The notes list the vanishing of several cusp-form spaces, integral Fourier coefficients, the Eisenstein series and \(\Delta=q-24q^2+252q^3-\cdots\).',r'For level one, \(M_*\) over \(\mathbb C\) is generated by \(E_4,E_6\), and \(S_k=\Delta M_{k-12}\), where \(\Delta=(E_4^3-E_6^2)/1728\). In particular \(S_k=0\) for \(k=2,4,6,8,10,14\) and all odd \(k\). A basis with integral Fourier coefficients can be chosen; this does not mean every complex linear combination has integral coefficients.',r'\citet[Section~1 and examples]{kohnenzagier1984periods} use the rational Fourier structure and the discriminant form. The displayed coefficients and vanishing statements are standard pre-1987 material.',('kohnenzagier1984periods',))
item(700,'P001334','definition','Normalized Eisenstein series and Fourier coefficients',r'The primitive lattice sum defining \(E_k\) has denominator power 2, whereas the transformation weight and subsequent examples use \(k\).',r'For even \(k\ge4\), \(E_k(z)=\tfrac12\sum_{(c,d)=1}(cz+d)^{-k}=1-(2k/B_k)\sum_{n\ge1}\sigma_{k-1}(n)q^n\). Absolute convergence justifies rearrangement. In particular \(E_4=1+240(q+9q^2+28q^3+73q^4+\cdots)\). Weight 2 requires quasimodular or nonholomorphic corrections.',r'The Eisenstein normalizations and their products are treated in \citet[Sections~1--2]{kohnenzagier1984periods}. The denominator exponent in the notebook is an error, not a different normalization.',('kohnenzagier1984periods',),correctness='false as written')
item(700,'P001334-P001335','theorem','Hecke eigenforms and coefficient multiplicativity',r'An Euler form is characterized by multiplicative coefficients, and the Hecke operators have a simultaneous eigenbasis.',r'On \(S_k(SL_2(\mathbb Z))\), the usual Hecke operators commute and are self-adjoint for the Petersson product. A normalized eigenform \(f=\sum a_nq^n\), \(a_1=1\), satisfies \(T_nf=a_nf\) and \(a_ma_n=\sum_{d\mid(m,n)}d^{k-1}a_{mn/d^2}\). Coprime multiplicativity alone omits the prime-power relation needed for the full Hecke characterization.',r'\citet[Section~1]{zagier1977quadratic} fixes the normalized eigenbasis and its eigenvalues; \citet[Section~1]{kohnenzagier1984periods} uses the same Hecke structure in the period rationality theorem.',('zagier1977quadratic','kohnenzagier1984periods'))
item(700,'P001335','construction','Normalization of the slash action and Hecke operators',r'The \(GL_2^+\) slash action includes \(\det(A)^{k/2}\). The displayed coset definition of \(T_n\) also has a factor \(1/2\), while the examples have \(T_1=1\).',r'Use \((f|_kA)(z)=\det(A)^{k/2}(cz+d)^{-k}f(Az)\) and \(T_nf=n^{k/2-1}\sum_{A\in SL_2(\mathbb Z)\backslash M_n}f|_kA\), with each coset counted once. Then \(T_1=1\) and \(T_2f=2^{k-1}f(2z)+\tfrac12f(z/2)+\tfrac12f((z+1)/2)\). A separate factor \(1/2\) is appropriate only if both signs are deliberately counted.',r'The normalization is the one underlying \citet[Section~1]{zagier1977quadratic}. The notebook combines the quotient convention with the double-counting factor; its concrete \(T_2\) example identifies the intended correction.',('zagier1977quadratic',),correctness='false as written')
item(700,'P001336','theorem','Weighted Bergman reproducing identity',r'A half-plane integral reproduces a holomorphic function with constant \((-1)^{k/2}\pi/[2^{k-2}(k-1)]\).',r'For even \(k\ge2\), \(w\in\mathbb H\), and a holomorphic function in the weighted Bergman space for measure \(y^{k-2}dx\,dy\), \[\int_{\mathbb H}\frac{f(z)y^{k-2}}{(\bar z-w)^k}\,dx\,dy=\frac{(-1)^{k/2}\pi}{2^{k-2}(k-1)}f(w).\] A growth or integrability hypothesis is essential; an arbitrary holomorphic function need not have the displayed integral.',r'This kernel calculation is the analytic ingredient in \citet[Section~2]{zagier1977quadratic}. Its use for automorphic forms follows by unfolding a convergent Poincar\'e kernel, not by assuming every modular form is square-integrable over the entire half-plane.',('zagier1977quadratic',))
item(700,'P001336-P001337','method','The Hecke kernel and its spectral trace',r'A determinant-\(n\) matrix sum is expanded in a Hecke eigenbasis; setting the two variables on the appropriate diagonal yields \(\operatorname{Tr}T_n\).',r'For even \(k>2\), the convergent holomorphic kernel obtained by summing the weighted Bergman kernel over integer matrices of determinant \(n\) represents the normalized Hecke operator on the finite-dimensional Petersson space \(S_k\). Its spectral expansion runs over \(\dim S_k\) eigenforms, with reciprocal Petersson norms and eigenvalues \(a_j(n)\). Integrating the diagonal gives \(\sum_{j=1}^{\dim S_k}a_j(n)\).',r'\citet[Section~2 and equations~(14)--(19)]{zagier1977quadratic} develops this kernel method. The notebook upper summation bound \(n\) in the eigenform sum is a transcription-faithful mathematical slip: the number of eigenforms does not depend on the Hecke index.',('zagier1977quadratic',),correctness='false as written')
item(700,'P001337-P001338','construction','Binary quadratic forms in the trace calculation',r'Matrices of determinant \(n\) are reindexed by \(t=a+d\) and \(Q=[c,d-a,-b]\), with discriminant \(t^2-4n\), and the associated real-analytic kernel is integrated.',r'The matrix-to-form substitution has \(\operatorname{disc}(Q)=t^2-4n\). The elliptic contribution comes from negative discriminants with stabilizer weights. Positive nonsquare discriminants cancel in the specialized trace calculation, whereas positive squares contribute the divisor term; the scalar discriminant-zero contribution must also be retained. Sign pairs must be counted consistently with the initial factor \(1/2\).',r'\citet[Section~1, equations~(17)--(23), and Sections~3--4]{zagier1977quadratic} explicitly separates these cases. The notebook sentence about discriminants cannot be read as saying that all nonnegative contributions vanish.',('zagier1977quadratic',),correctness='false as written')
item(700,'P001338-P001339','theorem','The Eichler--Selberg trace formula at level one',r'The final trace is a finite sum of weighted class numbers and a divisor correction.',r'For even \(k\ge4\) and \(n\ge1\), put \(p_k(t,n)=[X^{k-2}](1-tX+nX^2)^{-1}\). Write \(H(D)\) for the Hurwitz weighted class number of negative discriminant \(D\), with \(H(0)=-1/12\). Then \[\operatorname{Tr}(T_n|S_k)=-\frac12\sum_{t^2\le4n}p_k(t,n)H(t^2-4n)-\frac12\sum_{d\mid n}\min(d,n/d)^{k-1}.\] The \(D=0\) convention incorporates the scalar term when \(n\) is a square.',r'This is the pre-existing Eichler--Selberg formula, recovered in \citet[Section~1, equation~(23)]{zagier1977quadratic}. The notebook gives its kernel derivation, not a new trace formula. Weight 2 is excluded because its correction terms differ.',('zagier1977quadratic',),correctness='correct with missing hypotheses')
item(700,'P001339','remark','Hurwitz weights and the trace polynomials',r'A table lists class numbers and \(p_2=1,p_3=t,p_4=t^2-n\), with a tentative identification as Legendre polynomials.',r'The polynomial recursion is \(p_{k+1}=tp_k-np_{k-1}\), so \(p_k(t,n)=n^{(k-2)/2}U_{k-2}(t/(2\sqrt n))\) for \(n>0\), where \(U_j\) is the Chebyshev polynomial of the second kind. Hurwitz numbers include imprimitive forms: \(H(-3)=1/3\), \(H(-4)=1/2\), \(H(-16)=3/2\), and \(H(-32)=3\).',r'\citet[equations~(18), (20)]{zagier1977quadratic} specifies both the generating polynomial and the imprimitive class-number weights. The notebook table entry 2 for discriminant \(-32\) counts only the primitive order and is not the required Hurwitz number.',('zagier1977quadratic',),correctness='false as written')
item(700,'P001340','definition','Nonholomorphic Eisenstein series and Rankin unfolding',r'The primitive Eisenstein sum is integrated against an invariant function, leaving the Mellin transform of its constant Fourier term.',r'For \(\operatorname{Re}s>1\), set \(E(z,s)=\tfrac12\sum_{(c,d)=1}y^s|cz+d|^{-2s}\). For a smooth automorphic \(F\) with sufficient decay, \[\int_{SL_2(\mathbb Z)\backslash\mathbb H}F(z)E(z,s)\,\frac{dx\,dy}{y^2}=\int_0^\infty a_0(y)y^{s-2}\,dy,\quad a_0(y)=\int_0^1F(x+iy)\,dx.\] Complex conjugation may be inserted consistently on both sides, not on one side only.',r'\citet[Section~1]{zagier1981eisenstein} gives this transform, and \citet[Sections~1--2]{zagier1982rankin} treats functions of nonrapid decay by explicit regularization. The latter paper was received in June 1981 and published in volume 28 (1982).',('zagier1981eisenstein','zagier1982rankin'))
item(700,'P001340-P001341','theorem','Completion, continuation, and poles of the Eisenstein series',r'The notes assert a functional equation using \((2\pi)^s\Gamma(s)E(z,s)\), and list poles at 1 and half of zeta zeros.',r'The correct completion for the primitive sum is \(E^*(z,s)=\pi^{-s}\Gamma(s)\zeta(2s)E(z,s)\). It is invariant under \(s\mapsto1-s\), with its standard simple poles at 0 and 1. The uncompleted series has residue \(3/\pi\) at 1; zeros of \(\zeta(2s)\) give possible poles after division, subject to cancellation. Multiplying by \(\Gamma(s)\) alone does not give the stated symmetry.',r'\citet[Section~1]{zagier1981eisenstein} supplies the exact completion and residue. The missing zeta factor and the power of \(\pi\) are material errors in the recorded formula.',('zagier1981eisenstein',),correctness='false as written')
item(700,'P001341-P001342','theorem','Horocycle averages and the Riemann hypothesis',r'The constant term is said to tend to the average over the fundamental domain, with oscillations of size \(y^{3/4}\). The normalization \(3/\pi\) disappears in one displayed formula.',r'For suitable smooth compactly supported automorphic \(F\), \(a_0(y)\to(3/\pi)\int_{\Gamma\backslash\mathbb H}F\,d\mu\) as \(y\downarrow0\). Mellin poles associated with zeta zeros control finer terms. A bound of the form \(O_F(y^{3/4-\varepsilon})\) for all such tests is a Riemann-hypothesis strength assertion; it is not an unconditional rate for every measurable invariant function.',r'\citet[Section~1 and the horocycle discussion]{zagier1981eisenstein} explains the connection between equidistribution remainders and zeta zeros. The current unresolved status of RH is independently recorded by \citet{clay2026riemann}.',('zagier1981eisenstein','clay2026riemann'),cls='C',correctness='false as written',problem='GP-1986-61',worth=r'The statement is useful as an exact conditional implication and a normalization check, but proving its full Riemann-hypothesis strength is not a bounded chapter project.',status=r'As of 12 November 2026, qualitative equidistribution under the stated test-function hypotheses is established; the universal RH-strength remainder is conditional. The notebook should not be read as an announced proof of RH.')
item(700,'P001342','construction','Quadratic-field periods and toroidal automorphic forms',r'Toroidal integrals of the Eisenstein series contain a quadratic-field zeta function, and therefore vanish at suitable zeros of \(\zeta(s)\).',r'For a nonsplit rational torus attached to a quadratic field, the appropriately normalized toroidal period of an Eisenstein series factors into a Hecke L-function product. The toroidal subspace consists of automorphic forms whose periods over every such torus vanish. Analytic continuation and the exact normalization are required at zeros and poles; one cannot simply substitute a singular quotient.',r'\citet[Sections~2--4]{zagier1981eisenstein} develops the proposal already before the talk. \citet[main theorem]{cornelissenlorscheid2011toroidal}, first circulated in June 2009 and revised in August 2011, identifies the Eisenstein-derivative part through zero multiplicities and the cuspidal part through central L-values.',('zagier1981eisenstein','cornelissenlorscheid2011toroidal'),match='exact',status=r'As of 12 November 2026, the later structural theorem clarifies the toroidal space, including derivatives at multiple zeros. It does not prove that all zeta zeros lie on the critical line.')
item(700,'P001342-P001343','question','A unitary realization of the zeta-zero spectrum',r'The notes form a span \(W\) of quadratic-form transforms and an orthogonal complement \(V\), note Laplacian invariance, and suggest that unitarity of the corresponding representation would imply RH.',r'The identifiable question is whether the toroidal construction can be supplied with the required positive invariant Hilbert structure and spectral identification so that the relevant Eisenstein parameters must lie on the unitary axis. One must specify the function space, topology, quotient or orthogonal complement, and exclude unwanted spectrum. Formal invariance under the hyperbolic Laplacian alone proves none of these assertions.',r'\citet[final sections]{zagier1981eisenstein} already presents and cautions about this strategy. \citet{cornelissenlorscheid2011toroidal} describes the algebraic automorphic spectrum without supplying the hypothesized positivity. RH remains open according to \citet{clay2026riemann}.',('zagier1981eisenstein','cornelissenlorscheid2011toroidal','clay2026riemann'),cls='C',problem='GP-1986-61',worth=r'Worth preserving as a precisely conditional spectral strategy; the notebook leaves the functional-analytic object too unspecified for a new proof attempt here.',correctness='correct with missing hypotheses',confidence='medium',status=r'As of 12 November 2026, the proposed route has no verified positivity argument yielding RH. The special toroidal results cited above are not a solution of the Riemann hypothesis.')
problem('GP-1986-61','Riemann hypothesis in the toroidal and horocycle formulations',r'Do all nontrivial zeros of \(\zeta(s)\) satisfy \(\operatorname{Re}s=1/2\)? In the recorded approach, can toroidal spectral parameters be put in a suitable positive unitary realization, or equivalently can the requisite RH-strength horocycle remainders be proved under the stated test-function hypotheses?',['1986-700.15','1986-700.17'],r'Open as of 12 November 2026. The toroidal structure theorems and qualitative horocycle equidistribution are established, but the positivity and zero-location conclusions are not.',['zagier1981eisenstein','cornelissenlorscheid2011toroidal','clay2026riemann'])
correction('P001333','modular transformation law','determinant plus or minus 1','Use determinant +1 for the stated holomorphic action on the upper half-plane.','Matrices of negative determinant exchange the half-planes; compare the subsequent slash action and Zagier 1977.')
correction('P001334','Fourier expansion','exp(-2 pi i n z)','Use exp(+2 pi i n z) for holomorphy at infinity and the later q definition.','The later q convention and all displayed modular-form expansions fix the sign.')
correction('P001334','Eisenstein lattice sum','denominator squared','The denominator exponent must equal the modular weight k.','The manuscript examples E4 and E6 and their transformation laws require exponent k.')
correction('P001335','Hecke coset formula','extra factor 1/2','Remove it if cosets already identify opposite matrices; alternatively specify doubled representatives.','T1=identity and the displayed T2 formula fix the normalization.')
correction('P001337','spectral trace sum','sum of eigenforms through n','Sum through dim S_k.','The Hecke index n and the dimension of the cusp-form space are distinct.')
correction('P001339','class-number table','H(-32)=2','H(-32)=3 under the Hurwitz convention used in the trace formula.','The weight includes the primitive discriminant -32 contribution 2 and the imprimitive discriminant -8 contribution 1.')
correction('P001341','Eisenstein completion','(2 pi)^s Gamma(s) E','pi^(-s) Gamma(s) zeta(2s) E for the primitive sum.','Zagier 1981 Section 1 gives the symmetric completion.')
correction('P001342','horocycle limit','integral over fundamental domain without factor','Multiply the unnormalized hyperbolic integral by 3/pi.','The hyperbolic area of the modular fundamental domain is pi/3; the preceding formula has the correct factor.')
save()

# Record 701: critical values and rational structures.
item(701,'P001343','question','Two-colour map enumeration with a prescribed interface length',r'At the opening, maps with fixed numbers of black and white triangles and a prescribed boundary between colours are proposed.',r'Count rooted orientable planar maps of the specified face degrees with two face colours, tracking separately the numbers of both colours and the number of edges separating colours. Equivalently, use the corresponding formal two-matrix generating function, with separate vertex variables and mixed-propagator weight; unrooted counts require automorphism weights.',r'The two-matrix Ising solution of \citet{kazakov1986ising} treats this enumeration framework. The notebook does not fix rooting, degenerate faces, or a requested coefficient formula, so identification with the exact quartic parameterization is partial. The same variant returns at the end of record 702.',('kazakov1986ising',),cls='E',match='partial',verification='publisher metadata checked',confidence='medium',problem='GP-1986-63')
item(701,'P001343','theorem','Even and negative zeta-values and moduli Euler characteristics',r'Bernoulli formulas for \(\zeta(2n)\) and \(\zeta(1-2g)\) are related to the Euler characteristic of the moduli space; the list gives \(\zeta(-3)=1/252\).',r'For \(n\ge1\), \(\zeta(2n)=(-1)^{n+1}B_{2n}(2\pi)^{2n}/[2(2n)!]\) and \(\zeta(1-2n)=-B_{2n}/(2n)\). For \(g\ge2\), \(\chi_{\mathrm{orb}}(\mathcal M_{g,1})=\zeta(1-2g)\) and \(\chi_{\mathrm{orb}}(\mathcal M_g)=\zeta(1-2g)/(2-2g)\). Thus \(\zeta(-3)=1/120\), while \(\zeta(-5)=-1/252\).',r'The moduli-space formula is the main theorem of \citet{harerzagier1986euler}, published before this lecture. Marking one point and using the orbifold Euler characteristic are indispensable; replacing these by the ordinary Euler characteristic of unpointed Teichm\"uller space is false.',('harerzagier1986euler',),correctness='false as written')
item(701,'P001343-P001344','method','Eisenstein products and recurrences for even zeta-values',r'Identities such as \(E_4^2=E_8\) and \(E_4E_6=E_{10}\) yield recurrences for even zeta-values.',r'Level-one dimensions give \(E_4^2=E_8\) and \(E_4E_6=E_{10}\) for normalized Eisenstein series. Comparing their Fourier coefficients and the Bernoulli normalization produces convolution identities for divisor sums and even zeta-values. At weights with cusp forms, the Eisenstein product generally has a nonzero cuspidal component, which must be retained.',r'\citet[initial sections]{kohnenzagier1984periods} supplies the Eisenstein-product framework used later in the lecture. The assertion is an established technique, with the small-weight identities representing special dimension-one cases.',('kohnenzagier1984periods',))
item(701,'P001344-P001345','theorem','Mellin transform and functional equation of a cusp-form L-function',r'The completed Dirichlet series is expressed as an integral of \(f(iy)\), and inversion gives the reflection formula.',r'If \(f(z)=\sum_{n\ge1}a_nq^n\in S_k(SL_2(\mathbb Z))\), then initially in a right half-plane \(\Lambda(f,s)=(2\pi)^{-s}\Gamma(s)\sum a_nn^{-s}=\int_0^\infty f(iy)y^{s-1}\,dy\). Cuspidal decay at both ends makes the integral entire, and \(\Lambda(f,s)=(-1)^{k/2}\Lambda(f,k-s)\). This applies to each cusp form, without an eigenform hypothesis; Euler products need that additional hypothesis.',r'\citet[Section~1]{kohnenzagier1984periods} uses precisely these completed values and their functional equation in defining period polynomials.',('kohnenzagier1984periods',))
item(701,'P001345','theorem','The two periods of a normalized Hecke eigenform',r'The critical values split into even and odd groups, each rationally proportional to a period; the two periods are said probably to be transcendental.',r'For a normalized level-one Hecke eigenform \(f\) with coefficient field \(K_f\), there are nonzero periods \(\Omega_f^\pm\), defined up to \(K_f^\times\), such that the appropriately parity-normalized critical values \(L(f,m)/( (2\pi i)^m\Omega_f^{(-1)^m})\), \(1\le m\le k-1\), lie in \(K_f\). For rational Fourier coefficients, the normalized period ratios are rational. Absolute transcendence is a separate assertion and depends on specifying the normalization.',r'The period theorem predates the lecture; \citet[Theorem~1 and period-polynomial discussion]{kohnenzagier1984periods} gives the rational structures used here. The notebook\textquoteright s transcendence aside is not a proved part of that theorem.',('kohnenzagier1984periods',),correctness='correct with missing hypotheses')
item(701,'P001345','example','Critical periods of the discriminant form',r'A table expresses the integrals \(r_n=\int_0^\infty\Delta(iy)y^n\,dy\) in two periods, including a denominator 691.',r'For the real-coefficient weight-12 discriminant form, \(r_n=(2\pi)^{-n-1}\Gamma(n+1)L(\Delta,n+1)\), \(0\le n\le10\), and \(r_n=r_{10-n}\). The even-indexed and odd-indexed period vectors each span a rational line. Numerical values of the generators have no invariant meaning until the rational scaling convention is fixed.',r'\citet[examples and tables for weight 12]{kohnenzagier1984periods} gives the exact rational period relations. The occurrence of 691 belongs to these exact arithmetic ratios, not to a floating-point inference.',('kohnenzagier1984periods',),match='partial')
item(701,'P001345-P001347','method','Rankin unfolding of products of Eisenstein series',r'The Petersson product of \(f\) with \(G_{2n}G_{k-2n}\) is unfolded to a Dirichlet series involving \(a_m\sigma_{k-1-2n}(m)\). The written range makes one weight negative.',r'For even \(k\) and integers \(n\) with \(2n\ge4\), \(k-2n\ge4\), pair the holomorphic Eisenstein product with a weight-\(k\) cusp form. Absolute convergence in an auxiliary parameter, followed where necessary by analytic continuation, justifies unfolding. Fourier integration yields a Gamma factor \(\Gamma(k-1)=(k-2)!\), with conjugations consistent with the Petersson convention.',r'\citet[Rankin method and products of Eisenstein series]{kohnenzagier1984periods} gives this argument. The notebook\textquoteright s inequality \(k/2<n\le k-2\) is incompatible with its chosen weights; an admissible basic range is \(2\le n\le k/2-2\).',('kohnenzagier1984periods',),correctness='false as written')
item(701,'P001347','theorem','Hecke factorization of the Rankin Dirichlet series',r'The divisor-sum Dirichlet series factors into two L-values divided by an even zeta-value.',r'For a normalized level-one eigenform and a complex parameter \(a\), the identity \[\sum_{m\ge1}\frac{a_m\sigma_a(m)}{m^s}=\frac{L(f,s)L(f,s-a)}{\zeta(2s-a-k+1)}\] holds where the series and Euler products converge absolutely and elsewhere by meromorphic continuation. Setting \(s=k-1\), \(a=k-1-2n\) gives the notebook\textquoteright s quotient \(L(f,k-1)L(f,2n)/\zeta(2n)\), interpreted by continuation if needed.',r'\citet[Rankin product calculation]{kohnenzagier1984periods} uses the Hecke relation to obtain this factorization and derive period comparisons. The identity does not say that \(L(f,2n)/\zeta(2n)\) is independent of \(n\).',('kohnenzagier1984periods',))
item(701,'P001347-P001348','construction','Three rational structures on the cusp-form space',r'The lecture distinguishes rational Fourier coefficients and rational even and odd periods, and cites Kohnen--Zagier under the title ``Modular forms with rational coefficients''.',r'The Fourier expansion defines a rational structure on level-one cusp forms. Period polynomials, decomposed by parity, give two further rational structures after choosing the appropriate period scalings; Hecke equivariance relates them. The critical-period length for a weight-\(w\) form is \(w-2\), so writing \(S_{2k}\) while keeping the range \(0,\ldots,k-2\) mixes conventions.',r'The explicitly cited work is \citet{kohnenzagier1984periods}, whose actual title is \emph{Modular forms with rational periods}, published in 1984, not a new 1987 result. It contains the rational-structure comparison rather than the claimed equality of all normalized critical values.',('kohnenzagier1984periods',),correctness='false as written')
correction('P001343','negative zeta-values','zeta(-3)=1/252','zeta(-3)=1/120; zeta(-5)=-1/252.','Bernoulli formula zeta(1-2n)=-B_(2n)/(2n).')
correction('P001344','E4 Fourier series','coefficient 28 at q^2','The q^2 coefficient inside the divisor-sum series is 9; 28 belongs to q^3.','sigma_3(2)=9 and sigma_3(3)=28.')
correction('P001345','Eisenstein constant','-B_k/(2k) labelled zeta(1-k)','It is zeta(1-k)/2 for even k at least 2.','The Bernoulli formula has denominator k, not 2k.')
correction('P001345','range of Eisenstein product weights','k/2 < n <= k-2','For holomorphic weights at least 4 use 2 <= n <= k/2-2.','The stated product has weights 2n and k-2n.')
correction('P001346','Gamma integral factor','(k-1)!','(k-2)! for the displayed y^(k-2) integral.','The following page uses the corrected factorial; Gamma(k-1)=(k-2)!.')
correction('P001347','critical value conclusion','L(f,2n)/zeta(2n) independent of n','The relevant ratios become algebraic after division by one parity period; they are not all equal.','Kohnen--Zagier exact period theorem and its weight-12 table.')
correction('P001348','bibliographic title','Modular forms with rational coefficients','Modular forms with rational periods.','Author bibliography and opened 1984 original.','both','provenance')
save()

# Record 702: exact genus enumeration.
item(702,'P001349','definition','The rooted orientable gluing numbers',r'The lecture returns to pairings of \(2n\) polygon sides and counts them by the genus of the glued surface.',r'The same numbers \(\epsilon_g(n)\) of 1986-700.2 are used: all sides retain their cyclic labels and each pair is glued with opposite induced boundary orientation. Euler\textquoteright s relation is \(V-n+1=2-2g\), hence \(V=n+1-2g\). Pictures suggesting prohibitions on special side pairings must be separated from the unrestricted Harer--Zagier count.',r'\citet[Theorem~2]{harerzagier1986euler} gives the already established formula. The matrix computation below uses the unrestricted pairing ensemble, including adjacent pairings; imposing the pictured restrictions would define a different enumeration.',('harerzagier1986euler',),problem='GP-1986-62')
item(702,'P001350-P001351','method','Gaussian integration by parts and Wick contractions',r'A Gaussian Hermitian matrix integral and an integration-by-parts identity produce pairings of the factors in a trace.',r'For a centred Hermitian Gaussian matrix with covariance \(\mathbb E M_{ij}M_{kl}=N^{-1}\delta_{il}\delta_{jk}\), Wick\textquoteright s rule pairs entries and each contraction contributes that covariance. Equivalently, Gaussian integration by parts differentiates a polynomial observable against its covariance. The measure is normalized to expectation one; treating all complex off-diagonal entries as independent real entries would give wrong constants.',r'\citet[matrix-integral proof of Theorem~2]{harerzagier1986euler} and \citet[Gaussian diagrammatics]{bessisitzyksonzuber1980graphical} give this exact combinatorial method, established before the talk.',('harerzagier1986euler','bessisitzyksonzuber1980graphical'))
item(702,'P001351','theorem','Topological expansion of a Gaussian trace moment',r'Index cycles are identified with vertices of the glued polygon and the power of \(N\) records genus.',r'With the covariance just specified, \(\mathbb E[N^{-1}\operatorname{Tr}M^{2n}]=\sum_{g=0}^{\lfloor n/2\rfloor}\epsilon_g(n)N^{-2g}\). For a pairing, the number of free index loops is \(V=n+1-2g\), while the \(n\) propagators and normalized trace contribute \(N^{-n-1}\). This is a finite identity for every positive integer \(N\), not merely an asymptotic expansion.',r'This is the exact matrix interpretation in \citet[proof of Theorem~2]{harerzagier1986euler}. It connects to the earlier planar-enumeration occurrence 1982-565.1.',('harerzagier1986euler',))
item(702,'P001351-P001352','method','Eigenvalue density and Hermite polynomials',r'Diagonalization, Vandermonde determinants and orthogonal polynomials reduce the matrix moment to one-dimensional Gaussian integrals.',r'For a Gaussian Hermitian ensemble, write the Vandermonde as a determinant of monic Hermite polynomials orthogonal for the chosen Gaussian weight. Integrating all but one eigenvalue gives the one-point density as the Gaussian weight times \(\sum_{j=0}^{N-1}P_j(x)^2/h_j\). Its \(2n\)-th moment equals \(\mathbb E\operatorname{Tr}M^{2n}\). The choice \(e^{-x^2}\) versus \(e^{-x^2/2}\) rescales both the polynomials and the moments.',r'\citet[Gaussian integral computation]{harerzagier1986euler} gives this reduction. The notebook shifts Gaussian conventions and indices; these cannot be combined without rescaling.',('harerzagier1986euler',),correctness='correct with missing hypotheses')
item(702,'P001352','remark','Stochastic quantization as an alternative matrix method',r'A remark attributes a Markov-process approach to Parisi.',r'The identifiable method realizes a Euclidean field or matrix distribution as an invariant law of a Langevin process, with noise and drift satisfying the appropriate fluctuation-dissipation relation. For a matrix model, existence of the invariant probability and convergence need hypotheses on the potential. This remark does not specify a new stochastic dynamics.',r'The seminar had already recorded stochastic quantization in 1982-565.2. Its role here is an alternative computational viewpoint, while the actual enumeration proceeds by the Gaussian integral; see the established graphical framework in \citet{bessisitzyksonzuber1980graphical}.',('bessisitzyksonzuber1980graphical',),match='thematic only',confidence='medium')
item(702,'P001353','theorem','The Harer--Zagier moment generating function',r'Two generating formulas are written with double-factorial and normalization shifts that conflict with the zeroth moment.',r'Let \(C_n(N)=\sum_g\epsilon_g(n)N^{n+1-2g}\), with \(C_0(N)=N\). Then, as a formal power series, \[1+2\sum_{n\ge0}\frac{C_n(N)}{(2n-1)!!}x^{n+1}=\left(\frac{1+x}{1-x}\right)^N,\quad (-1)!!=1.\] Equivalently \(\sum_{N\ge0}C_n(N)t^N=(2n-1)!!\,t(1+t)^n/(1-t)^{n+2}\). These are unnormalized polynomial moments; dividing by powers of \(N\) gives the normalized trace moments.',r'\citet[Theorem~2 and generating-function proof]{harerzagier1986euler} gives the exact generating identity. The constant and first coefficients are decisive normalization checks; the recorded formula cannot use \((2n)!!\) with the same moments.',('harerzagier1986euler',),correctness='false as written')
item(702,'P001353-P001354','theorem','Closed genus formula and the Harer--Zagier recursion',r'The lecture extracts a coefficient of a power of a hyperbolic-tangent expression to obtain the genus count.',r'For \(0\le2g\le n\), \[\epsilon_g(n)=\frac{(2n)!}{(n+1)!(n-2g)!}[u^{2g}]\left(\frac{u/2}{\tanh(u/2)}\right)^{n+1}.\] Equivalently, \((n+1)\epsilon_g(n)=(4n-2)\epsilon_g(n-1)+(2n-1)(n-1)(2n-3)\epsilon_{g-1}(n-2)\), with the usual zero conventions and \(\epsilon_0(0)=1\). In particular genus zero gives Catalan numbers.',r'These are \citet[Theorem~2 and displayed recurrence]{harerzagier1986euler}. The theorem was published in 1986, so the March 1987 presentation is expository. The square-root substitution in the notebook needs a factor-of-two correction to agree with the \(u/2\) convention.',('harerzagier1986euler',),correctness='false as written',problem='GP-1986-62')
item(702,'P001354','question','Maps with triangular faces and a marked polygonal boundary',r'Variants add triangular faces, fix a \(2n\)-sided boundary and genus, or introduce two colours and an interface length.',r'A formal matrix model with a cubic interaction and an insertion \(\operatorname{Tr}M^{2n}\) generates orientable maps with triangular interaction vertices and one marked boundary, sorted by genus. More colours use several matrices and mixed covariances. Exact coefficient extraction depends on rooting and whether the specified polygons are faces of the primal or dual map.',r'The graphical construction is established in \citet{bessisitzyksonzuber1980graphical}; the Ising specialization is \citet{kazakov1986ising}. These references verify a method for the variants, not one unique numerical formula, because the notebook leaves the counting conventions unstated.',('bessisitzyksonzuber1980graphical','kazakov1986ising'),match='partial',confidence='medium',problem='GP-1986-63')
problem('GP-1986-62','Orientable gluings of a labelled polygon by genus',r'For a labelled oriented \(2n\)-gon, count orientation-reversing pairings of its sides whose quotient has genus \(g\), with cyclic rotations kept distinct.',['1986-700.2','1986-702.1','1986-702.7'],r'Solved before the recorded discussions by Harer and Zagier (1986), with an exact coefficient formula, a recurrence, and a Gaussian-matrix derivation. As of 12 November 2026 this is an established enumeration theorem.',['harerzagier1986euler'])
problem('GP-1986-63','Coloured planar maps with controlled face counts and interfaces',r'Enumerate rooted orientable planar maps with specified numbers of faces of the prescribed degrees and colours, and a specified number of edges between unlike colours; specify primal/dual and rooting conventions before extracting coefficients.',['1986-701.1','1986-702.8'],r'As of 12 November 2026, formal multi-matrix generating functions and the planar Ising solution provide the recorded framework. The notebook does not select a unique finer counting convention, so no unsolved numerical problem is inferred.',['bessisitzyksonzuber1980graphical','kazakov1986ising'])
correction('P001353','moment integrand','lambda^(2k) for the n-th even moment','Use lambda^(2n), with the Gaussian scaling fixed consistently.','The moment being calculated is indexed by n; k is the orthogonal-polynomial summation index.')
correction('P001353','Harer--Zagier generating series','normalization using (2n)!!','For C_n(N), use 1+2 sum C_n(N)x^(n+1)/(2n-1)!!=((1+x)/(1-x))^N.','The zeroth moment is N and the first is N^2; the opened original gives the exact normalization.')
correction('P001354','hyperbolic-tangent coefficient formula','square-root scaling inconsistent with u/2','Use coefficient [u^(2g)] of ((u/2)/tanh(u/2))^(n+1).','Harer--Zagier Theorem 2; the n=2,g=1 coefficient must equal 1.')
